-- 06-team-seasons: uploaded workbook snapshot. Run entire file, then Write Changes.
-- Save pending edits and take a backup first. No BEGIN/COMMIT needed in DB Browser.
-- Identical reruns are safe; changed existing records are never overwritten.
PRAGMA foreign_keys=ON;
SAVEPOINT afl_season_6;
CREATE TEMP TABLE afl_season_import_stamp(effective_at TEXT NOT NULL);
CREATE TEMP TABLE afl_season_6_0 AS SELECT id, season_id, team_id, division_id, abbreviation, location, nickname, logo_url, home_jersey_url, away_jersey_url, home_uniform_url, away_uniform_url, primary_color, secondary_color, third_color, cap_space FROM team_seasons WHERE 0;
CREATE TEMP TABLE afl_season_6_guard(ok INTEGER);
CREATE TEMP TRIGGER afl_season_6_check BEFORE INSERT ON afl_season_6_guard
BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM leagues WHERE id='36c6e53f-7be2-5a94-84a8-0df871aae9fd' AND name='AFL') THEN RAISE(ROLLBACK,'Missing AFL league.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM seasons WHERE id='97808f43-a0d5-5251-bf8d-fae1643c8258' AND league_id='36c6e53f-7be2-5a94-84a8-0df871aae9fd') THEN RAISE(ROLLBACK,'Import season (05) first.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_season_6_0 i LEFT JOIN teams t ON t.id=i.team_id WHERE i.team_id IS NOT NULL AND (t.id IS NULL OR t.league_id<>'36c6e53f-7be2-5a94-84a8-0df871aae9fd')) THEN RAISE(ROLLBACK,'Team IDs missing or belong to another league.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_season_6_0 i LEFT JOIN divisions d ON d.id=i.division_id WHERE d.id IS NULL OR d.league_id<>'36c6e53f-7be2-5a94-84a8-0df871aae9fd') THEN RAISE(ROLLBACK,'Division IDs missing or belong to another league.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_season_6_0 i JOIN team_seasons t ON t.id=i.id WHERE t.season_id IS NOT i.season_id OR t.team_id IS NOT i.team_id OR t.division_id IS NOT i.division_id OR t.abbreviation IS NOT i.abbreviation OR t.location IS NOT i.location OR t.nickname IS NOT i.nickname OR t.logo_url IS NOT i.logo_url OR t.home_jersey_url IS NOT i.home_jersey_url OR t.away_jersey_url IS NOT i.away_jersey_url OR t.home_uniform_url IS NOT i.home_uniform_url OR t.away_uniform_url IS NOT i.away_uniform_url OR t.primary_color IS NOT i.primary_color OR t.secondary_color IS NOT i.secondary_color OR t.third_color IS NOT i.third_color OR t.cap_space IS NOT i.cap_space) THEN RAISE(ROLLBACK,'team_seasons: existing ID has different data; no records overwritten.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_season_6_0 i JOIN team_seasons t ON t.season_id=i.season_id AND (t.team_id=i.team_id OR lower(t.abbreviation)=lower(i.abbreviation)) WHERE t.id<>i.id) THEN RAISE(ROLLBACK,'team_seasons: natural key belongs to another ID.') END;
END;
DROP TRIGGER afl_season_6_check;
DROP TABLE afl_season_6_guard;
DROP TABLE afl_season_6_0;
DROP TABLE afl_season_import_stamp;
RELEASE SAVEPOINT afl_season_6;
PRAGMA foreign_key_check;
SELECT 'team_seasons' AS imported_table, COUNT(*) AS reviewed_records_present FROM team_seasons WHERE id IN ('e75274d2-2cf4-5373-86c3-8f32c3b925d7', '0092680d-cc39-5df9-817a-fea5b2d59059', 'b51d49e3-1690-5610-890d-798babd621cd', 'edcb07f6-3e55-5215-9252-60a946cda95c', 'd9b86c80-f3a7-58cc-b13f-9320f1118c39', '46ac7f4e-31ff-5c91-a192-f542ccd7e350', '4095c639-ba91-5a25-9a3f-2b26b5058aa8', '9fa3ca0a-d57c-5545-9b81-26050ce507b1', 'c9d91948-e5cf-55fd-9903-f97d3bdcbfbd', '54f22c96-c4c3-5a0a-84df-80d60981bb5b');
